function getPickupFloorsRequiringInventory() {
    const floors = new Set();

    if (window.selectedPickupFloors && window.selectedPickupFloors.size > 0) {
        Array.from(window.selectedPickupFloors).forEach((floorName) => {
            const value = String(floorName || '').trim();
            if (value) floors.add(value);
        });
    }

    Array.from(document.querySelectorAll('#pickup-floors-selector .pickup-floor-selector-btn.selected'))
        .map((btn) => String(btn.getAttribute('data-floor') || '').trim())
        .filter(Boolean)
        .forEach((floorName) => floors.add(floorName));

    Array.from(document.querySelectorAll('#house-removal-inventory-section .floor-inventory-block[data-floor]'))
        .map((block) => String(block.getAttribute('data-floor') || '').trim())
        .filter(Boolean)
        .forEach((floorName) => floors.add(floorName));

    if (window.multiFloorInventory && typeof window.multiFloorInventory === 'object') {
        Object.keys(window.multiFloorInventory)
            .map((floorName) => String(floorName || '').trim())
            .filter(Boolean)
            .forEach((floorName) => floors.add(floorName));
    }

    return getOrderedFloorList(Array.from(floors));
}

function getSelectedPickupFloorsMissingInventory() {
    const selectedFloors = getPickupFloorsRequiringInventory();
    if (selectedFloors.length === 0) {
        return [];
    }

    return selectedFloors.filter((floorName) => {
        const floorItems = window.multiFloorInventory && window.multiFloorInventory[floorName];
        if (!floorItems || typeof floorItems !== 'object') {
            return true;
        }
        return !Object.values(floorItems).some((qty) => (parseInt(qty, 10) || 0) > 0);
    });
}

function hasCurrentHouseRemovalInventorySelection() {
    const inventoryRoot = document.getElementById('inventory-card-container');
    if (!inventoryRoot || inventoryRoot.style.display === 'none') {
        return false;
    }

    const qtyDisplays = Array.from(inventoryRoot.querySelectorAll('.room-item-quantity-display'));
    return qtyDisplays.some((input) => (parseInt(input.value, 10) || 0) > 0);
}

function getHouseRemovalMissingInventoryTarget() {
    const serviceValue = getActiveServiceValue();
    if (serviceValue !== 'House Removals') {
        return null;
    }

    if (!hasCurrentHouseRemovalInventorySelection()) {
        return document.getElementById('inventory-card-container')
            || document.getElementById('house-removal-inventory-section')
            || document.getElementById('pickup-floor-select');
    }

    const selectedFloors = getPickupFloorsRequiringInventory();
    if (selectedFloors.length === 0) {
        return null;
    }

    const missingFloors = selectedFloors.filter((floorName) => {
        const floorItems = window.multiFloorInventory && window.multiFloorInventory[floorName];
        if (!floorItems || typeof floorItems !== 'object') {
            return true;
        }
        return !Object.values(floorItems).some((qty) => (parseInt(qty, 10) || 0) > 0);
    });

    if (missingFloors.length > 0 || !hasAnyInventorySelection()) {
        return document.getElementById('inventory-card-container')
            || document.getElementById('house-removal-inventory-section')
            || document.getElementById('pickup-floor-select');
    }

    return null;
}

function updateStep3InventoryWarning() {
    const inventoryCardContainer = document.getElementById('inventory-card-container');
    if (!inventoryCardContainer) return;

    const inventorySection = document.getElementById('house-removal-inventory-section');
    const warningHost = inventorySection || inventoryCardContainer;
    const warningAnchor = inventorySection
        ? (inventorySection.querySelector('.inventory-floor-title') || inventorySection.firstElementChild || null)
        : (inventoryCardContainer.firstElementChild || null);

    let warningEl = document.getElementById('step3-inventory-warning');
    if (!warningEl) {
        warningEl = document.createElement('div');
        warningEl.id = 'step3-inventory-warning';
        warningEl.style.cssText = `
            display: none;
            margin: 10px 0 14px;
            padding: 10px 12px;
            border-left: 4px solid #f59e0b;
            background: #fffbeb;
            color: #92400e;
            border-radius: 6px;
            font-size: 0.9rem;
            font-weight: 600;
        `;
    }

    if (warningAnchor) {
        if (warningEl.parentElement !== warningHost || warningEl.nextElementSibling !== warningAnchor) {
            warningHost.insertBefore(warningEl, warningAnchor);
        }
    } else if (warningEl.parentElement !== warningHost) {
        warningHost.appendChild(warningEl);
    }

    const isStep3 = (document.body.getAttribute('data-form-step') === '3' || document.body.getAttribute('data-current-step') === '3');
    const inventoryRequired = isInventoryInputRequiredForStep3();
    const missingFloors = getSelectedPickupFloorsMissingInventory();

    if (isStep3 && inventoryRequired && missingFloors.length > 0) {
        warningEl.textContent = `Add at least 1 item to: ${missingFloors.join(', ')}`;
        warningEl.style.display = 'block';
    } else {
        warningEl.style.display = 'none';
    }
}

function isInventoryInputRequiredForStep3() {
    const serviceValue = (document.getElementById('item-description-hidden')?.value || '').trim();
    if (isCustomizedInventoryService(serviceValue)) {
        return false;
    }
    const inventoryCardContainer = document.getElementById('inventory-card-container');
    if (!inventoryCardContainer) return false;
    return inventoryCardContainer.style.display !== 'none' && inventoryCardContainer.offsetParent !== null;
}

function ensureMultiFloorInventoryVisible() {
    const inventoryCardContainer = document.getElementById('inventory-card-container');
    const multiFloorContainer = document.querySelector('#house-removal-inventory-section .floors-inventory-container');
    if (!inventoryCardContainer || !multiFloorContainer) return;

    if (inventoryCardContainer.style.display === 'none') return;

    const hasBlocks = multiFloorContainer.children.length > 0;
    if (!hasBlocks) return;

    const basicRoomTabs = document.getElementById('room-tabs');
    const basicRoomContainer = document.getElementById('room-items-container');

    if (basicRoomTabs) basicRoomTabs.style.display = 'none';
    if (basicRoomContainer) basicRoomContainer.style.display = 'none';
    multiFloorContainer.style.display = '';
    document.body.classList.add('multi-floor-inventory-mode');
}

window.hasAnyInventorySelection = hasAnyInventorySelection;
window.isInventoryInputRequiredForStep3 = isInventoryInputRequiredForStep3;
window.updateStep3InventoryWarning = updateStep3InventoryWarning;
window.ensureMultiFloorInventoryVisible = ensureMultiFloorInventoryVisible;

document.addEventListener('click', function(event) {
    const editBtn = event.target.closest('.overview-edit-btn');
    if (editBtn) {
        event.preventDefault();
        const directOverviewEdit = (editBtn.getAttribute('data-overview-edit') || '').trim().toLowerCase();
        if (directOverviewEdit === 'addresses') {
            openOverviewEditModal('summary-addresses');
            return;
        }

        const moveEditAttr = (editBtn.getAttribute('data-edit-movers') || '').trim().toLowerCase();
        if (moveEditAttr) {
            openOverviewMoveEditModal(moveEditAttr === 'delivery' ? 'delivery' : 'pickup');
            return;
        }

        const card = editBtn.closest('.overview-item');
        const valueEl = card ? card.querySelector('.overview-item-value') : null;
        const valueId = valueEl ? valueEl.id : '';
        const overviewSection = document.querySelector('[data-form-step="8"]');
        const overviewVisible = !!(overviewSection && overviewSection.offsetParent !== null);

        // Address edits should open in-place editor whenever the overview is visible,
        // even if body step data is temporarily stale.
        if (overviewVisible && (valueId === 'summary-pickup-address' || valueId === 'summary-delivery-address')) {
            if (typeof window.openOverviewEditModal === 'function') {
                window.openOverviewEditModal(valueId);
            }
            return;
        }

        const currentStep = parseInt(document.body.dataset.formStep || '1', 10);
        if (currentStep === 8) {
            if (valueId === 'summary-pickup-floors' || valueId === 'summary-delivery-floors') {
                const isPickup = valueId === 'summary-pickup-floors';
                const targetStep = isPickup ? 3 : 5;
                if (typeof window.setFormStep === 'function') {
                    window.setFormStep(targetStep);
                }
                if (isPickup && typeof window.renderPickupFloorSelector === 'function') {
                    window.renderPickupFloorSelector();
                }
                if (!isPickup && typeof window.renderDeliveryFloorSelector === 'function') {
                    window.renderDeliveryFloorSelector();
                }
                if (!isPickup && typeof window.renderDeliveryFloors === 'function') {
                    window.renderDeliveryFloors();
                }
                const targetSelector = isPickup
                    ? document.getElementById('pickup-floors-selector')
                    : document.getElementById('delivery-floors-selector');
                const targetWrapper = isPickup
                    ? document.getElementById('pickup-room-list-wrapper')
                    : document.getElementById('item-organization-section');
                if (targetWrapper?.scrollIntoView) {
                    targetWrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
                } else if (targetSelector?.scrollIntoView) {
                    targetSelector.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
                return;
            }

            if (valueId) {
                if (typeof window.openOverviewEditModal === 'function') {
                    window.openOverviewEditModal(valueId);
                }
            }
            return;
        }
    }

    const manageBtn = event.target.closest('.overview-inventory-manage-btn');
    if (manageBtn) {
        event.preventDefault();
        const activeService = getActiveServiceValue();
        if (!isInventoryManageService(activeService)) {
            return;
        }
        const currentStep = parseInt(document.body.dataset.formStep || '1', 10);
        if (currentStep === 8) {
            const kind = (manageBtn.getAttribute('data-overview-inventory-kind') || 'pickup').trim().toLowerCase();
            if (kind === 'delivery' && isClearanceService(activeService)) {
                return;
            }
            const targetStep = kind === 'delivery' ? 5 : 3;
            if (typeof window.setFormStep === 'function') {
                window.setFormStep(targetStep);
            }
        }
        return;
    }

    const targetStep = parseInt((editBtn && editBtn.getAttribute('data-edit-step')) || '', 10);
    if (!Number.isFinite(targetStep)) return;
    if (typeof window.setFormStep === 'function') {
        window.setFormStep(targetStep);
    }
});

