    function getPackingRoomForItem(itemName) {
        if (itemName.includes(' - ')) {
            const prefix = itemName.split(' - ')[0].toLowerCase();
            if (PACKING_ROOM_CATS[prefix]) return prefix;
        }
        for (const [roomKey, items] of Object.entries(PACKING_ROOM_ITEMS_MAP)) {
            if (items.includes(itemName)) return roomKey;
        }
        return 'boxes';
    }

    function getServiceItemDisplayName(itemName) {
        if (!itemName || typeof itemName !== 'string') return itemName;
        const roomPrefixes = new Set(['hallway', 'shed', 'utility', 'living', 'dining', 'kitchen', 'office', 'bedrooms', 'bathrooms', 'garden', 'boxes']);
        const prefixedMatch = itemName.match(/^([A-Za-z]+)\s*-\s*(.+)$/);
        if (prefixedMatch) {
            const prefix = prefixedMatch[1].trim().toLowerCase();
            if (roomPrefixes.has(prefix)) {
                return prefixedMatch[2].trim();
            }
        }
        return itemName;
    }

    function parsePackingItemsSelection(raw) {
        if (!raw) return {};
        try {
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' ? parsed : {};
        } catch (error) {
            return {};
        }
    }

    function getCustomizedStyleItems() {
        const serviceValue = getActiveServiceValue();
        if (!isCustomizedInventoryService(serviceValue)) {
            return [];
        }

        const serializedItems = document.getElementById('customized-items-hidden')?.value || '';
        if (!serializedItems) {
            return [];
        }

        try {
            const parsedItems = JSON.parse(serializedItems);
            if (!Array.isArray(parsedItems)) {
                return [];
            }

            return parsedItems
                .map((item) => ({
                    name: String(item?.name || '').trim(),
                    qty: Math.max(1, parseInt(item?.quantity ?? item?.qty ?? 1, 10) || 1),
                    sourceFloor: String(item?.sourceFloor || '').trim()
                }))
                .filter((item) => !!item.name);
        } catch (error) {
            return [];
        }
    }

    function setPackingItemQty(itemName, qty, maxQty) {
        const hiddenInput = document.getElementById('service-packing-items');
        if (!hiddenInput) return;

        const state = parsePackingItemsSelection(hiddenInput.value);
        const clampedQty = Math.max(0, Math.min(maxQty, parseInt(qty, 10) || 0));

        if (clampedQty > 0) {
            state[itemName] = clampedQty;
        } else {
            delete state[itemName];
        }

        hiddenInput.value = Object.keys(state).length > 0 ? JSON.stringify(state) : '';
        hiddenInput.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function parseDisassemblyItemsSelection(raw) {
        if (!raw) return {};
        try {
            const parsed = JSON.parse(raw);
            return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
        } catch (error) {
            return {};
        }
    }

    function setDisassemblyItemQty(itemKey, qty, maxQty) {
        const hiddenInput = document.getElementById('service-disassembly-items');
        if (!hiddenInput) return;

        const state = parseDisassemblyItemsSelection(hiddenInput.value);
        const parsedQty = parseInt(qty, 10) || 0;
        const parsedMax = parseInt(maxQty, 10);
        const maxAllowed = Number.isFinite(parsedMax) && parsedMax > 0 ? parsedMax : Number.MAX_SAFE_INTEGER;
        const clampedQty = Math.max(0, Math.min(maxAllowed, parsedQty));

        if (clampedQty > 0) {
            state[itemKey] = clampedQty;
        } else {
            delete state[itemKey];
        }

        hiddenInput.value = Object.keys(state).length > 0 ? JSON.stringify(state) : '';
        hiddenInput.dispatchEvent(new Event('change', { bubbles: true }));
    }

