function setupRouteListeners() {
    const pickupInput = document.getElementById('pickup-address');
    const deliveryInput = document.getElementById('delivery-address');
    const pickupCity = document.getElementById('pickup-city');
    const deliveryCity = document.getElementById('delivery-city');
    const pickupPostcode = document.getElementById('pickup-postcode');
    const deliveryPostcode = document.getElementById('delivery-postcode');

    const syncHiddenCityFromPrimaryInputs = () => {
        const hiddenPickupCity = document.getElementById('pickup-city');
        const hiddenDeliveryCity = document.getElementById('delivery-city');
        if (hiddenPickupCity && pickupInput) {
            hiddenPickupCity.value = (pickupInput.value || '').trim();
        }
        if (hiddenDeliveryCity && deliveryInput) {
            hiddenDeliveryCity.value = (deliveryInput.value || '').trim();
        }
    };
    
    // Setup address autocomplete
    if (pickupInput) {
        setupAddressAutocomplete(pickupInput, 'pickup');
        pickupInput.addEventListener('input', syncHiddenCityFromPrimaryInputs);
        pickupInput.addEventListener('input', syncClearanceDeliveryFromPickup);
        pickupInput.addEventListener('blur', updateRouteIfReady);
        pickupInput.addEventListener('change', updateRouteIfReady);
        pickupInput.addEventListener('change', syncClearanceDeliveryFromPickup);
    }
    if (deliveryInput) {
        setupAddressAutocomplete(deliveryInput, 'delivery');
        deliveryInput.addEventListener('input', syncHiddenCityFromPrimaryInputs);
        deliveryInput.addEventListener('blur', updateRouteIfReady);
        deliveryInput.addEventListener('change', updateRouteIfReady);
    }
    if (pickupCity) pickupCity.addEventListener('change', updateRouteIfReady);
    if (deliveryCity) deliveryCity.addEventListener('change', updateRouteIfReady);

    const pickupAreaEircode = document.getElementById('pickup-area-eircode');
    const deliveryAreaEircode = document.getElementById('delivery-area-eircode');

    if (pickupAreaEircode) {
        setupAreaOrEircodeAutocomplete(pickupAreaEircode, 'pickup');
        pickupAreaEircode.addEventListener('blur', () => handleAreaOrEircodeLookup(pickupAreaEircode, 'pickup'));
        pickupAreaEircode.addEventListener('change', () => handleAreaOrEircodeLookup(pickupAreaEircode, 'pickup'));
        pickupAreaEircode.addEventListener('input', syncClearanceDeliveryFromPickup);
        pickupAreaEircode.addEventListener('change', syncClearanceDeliveryFromPickup);
    }
    if (deliveryAreaEircode) {
        setupAreaOrEircodeAutocomplete(deliveryAreaEircode, 'delivery');
        deliveryAreaEircode.addEventListener('blur', () => handleAreaOrEircodeLookup(deliveryAreaEircode, 'delivery'));
        deliveryAreaEircode.addEventListener('change', () => handleAreaOrEircodeLookup(deliveryAreaEircode, 'delivery'));
    }

    if (pickupPostcode) {
        setupPostcodeAutocomplete(pickupPostcode, 'pickup');
        pickupPostcode.addEventListener('blur', () => handleEircodeLookup(pickupPostcode, 'pickup'));
        pickupPostcode.addEventListener('change', () => handleEircodeLookup(pickupPostcode, 'pickup'));
        pickupPostcode.addEventListener('input', syncClearanceDeliveryFromPickup);
        pickupPostcode.addEventListener('change', syncClearanceDeliveryFromPickup);
    }
    if (deliveryPostcode) {
        setupPostcodeAutocomplete(deliveryPostcode, 'delivery');
        deliveryPostcode.addEventListener('blur', () => handleEircodeLookup(deliveryPostcode, 'delivery'));
        deliveryPostcode.addEventListener('change', () => handleEircodeLookup(deliveryPostcode, 'delivery'));
    }

    syncHiddenCityFromPrimaryInputs();
    syncClearanceDeliveryFromPickup();
}

